"""Seed investment theses (OMEGA brief) plus macro / geopolitical theses.

A rule says: "if an event matches this, it is evidence for/against the thesis".
  any      : phrases (word-boundary) - at least one must appear
  types    : event types the rule applies to (optional)
  regions  : regions that must ALL be present (optional)
  mode     : 'topic'    evidence direction follows the event's own direction (good news on the topic supports it)
             'inverse'  evidence direction is the opposite of the event direction (e.g. bad inflation news supports "inflation resurgence")
             'support'  always supports            'contradict' always contradicts
  w        : rule weight 0..1
"""
from __future__ import annotations

R = lambda any, mode="topic", w=1.0, types=None, regions=None: {"any": any, "mode": mode, "w": w, "types": types or [], "regions": regions or []}  # noqa: E731

